/** Local-only medication screens; only explicit confirmation creates an actual-use log. */
public class MainActivity extends Activity {
    private interface TimeChoices {List<Long> forDate(LocalDate date);}
    private int BG,INK,MUTED,TEAL,PALE,LINE,RED,SURFACE,ON_ACCENT;
    private boolean night,completedExpanded,laterExpanded,skippedExpanded,actionDialogOpen;
    private long nextTickDelay=60000;
    private final Handler ticker=new Handler(Looper.getMainLooper());
    private final Runnable refresh=new Runnable(){public void run(){if(page.equals(UiState.TODAY)&&body!=null&&!actionDialogOpen){ScrollView sc=(ScrollView)body.getParent();int y=sc.getScrollY();subtitle.setText(new SimpleDateFormat(getString(R.string.ui_date_header_pattern),Locale.getDefault()).format(new Date()));body.removeAllViews();today();sc.post(()->sc.scrollTo(0,y));}ticker.postDelayed(this,Math.min(nextTickDelay,TodayPlan.refreshDelay(System.currentTimeMillis())));}};
    private boolean selectedNight(){return Appearance.dark(getSharedPreferences("appearance",0).getString("mode","system"),(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);}
    private void applyAppearance(){night=selectedNight();setTheme(night?R.style.DarkTheme:R.style.LightTheme);Appearance.Palette c=Appearance.palette(night);BG=c.bg;INK=c.ink;MUTED=c.muted;TEAL=c.accent;PALE=c.soft;LINE=c.border;RED=c.danger;SURFACE=c.surface;ON_ACCENT=c.onAccent;}
    protected void onSaveInstanceState(Bundle b){b.putString("page",page);b.putString("range",statsRange);b.putBoolean("completed",completedExpanded);b.putBoolean("later",laterExpanded);b.putBoolean("skipped",skippedExpanded);super.onSaveInstanceState(b);}
    protected void onStop(){ticker.removeCallbacks(refresh);AlarmSelfTest.visibility(false);super.onStop();}
    private Store store;
    private LinearLayout root, body;
    private TextView subtitle;
    private String page=UiState.TODAY, statsRange=UiState.ALL;
    private final SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT);

    public void onCreate(Bundle b){AlarmSelfTest.appEntry(this,"app_launch");applyAppearance();super.onCreate(b);if(b!=null){page=UiState.page(b.getString("page"));statsRange=UiState.range(b.getString("range"));completedExpanded=b.getBoolean("completed");laterExpanded=b.getBoolean("later");skippedExpanded=b.getBoolean("skipped");}store=new Store(this);fmt.setLenient(false);render();handle(getIntent());}
    protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handle(i);}
    protected void onResume(){AlarmSelfTest.foregroundLaunch(this);super.onResume();fmt.setTimeZone(TimeZone.getDefault());if(store!=null){if(night!=selectedNight()){recreate();return;}Alarms.reschedule(this);render();ticker.removeCallbacks(refresh);ticker.postDelayed(refresh,Math.min(nextTickDelay,TodayPlan.refreshDelay(System.currentTimeMillis())));}}

    private void render(){
        nextTickDelay=60000;
        getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        int flags=getWindow().getDecorView().getSystemUiVisibility();int light=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;getWindow().getDecorView().setSystemUiVisibility(night?flags&~light:flags|light);
        if(Build.VERSION.SDK_INT>=29){getWindow().setStatusBarContrastEnforced(false);getWindow().setNavigationBarContrastEnforced(false);}
        root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(10),dp(16),0);root.setBackgroundColor(BG);
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView brand=txt(getString(R.string.ui_brand),16,true);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button settings=new Button(this);settings.setText(getString(R.string.ui_settings));settings.setAllCaps(false);styleButton(settings,false);top.addView(settings,new LinearLayout.LayoutParams(-2,dp(48)));settings.setOnClickListener(v->{page=UiState.SETTINGS;render();});root.addView(top);
        TextView sub=txt(page.equals(UiState.TODAY)?new SimpleDateFormat(getString(R.string.ui_date_header_pattern),Locale.getDefault()).format(new Date()):pageLabel(page),14,false);subtitle=sub;sub.setPadding(0,dp(2),0,dp(4));root.addView(sub);
        ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(12),0,dp(20));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout tabs=new LinearLayout(this);tabs.setPadding(0,dp(5),0,dp(5));for(String s:new String[]{UiState.TODAY,UiState.MEDICATIONS,UiState.STATS,UiState.HISTORY}){Button b=new Button(this);b.setText(pageLabel(s));b.setAllCaps(false);styleButton(b,s.equals(page));tabs.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{page=s;render();});}root.addView(tabs);setContentView(root);
        if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets z=in.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(18),dp(14)+z.top,dp(18),z.bottom);return in;});root.requestApplyInsets();
        if(page.equals(UiState.TODAY))today();else if(page.equals(UiState.MEDICATIONS))meds();else if(page.equals(UiState.STATS))statistics();else if(page.equals(UiState.HISTORY))history();else settings();
    }

    private String pageLabel(String id){if(UiState.TODAY.equals(id))return getString(R.string.ui_today);if(UiState.MEDICATIONS.equals(id))return getString(R.string.ui_medications);if(UiState.STATS.equals(id))return getString(R.string.ui_statistics);if(UiState.HISTORY.equals(id))return getString(R.string.ui_history);return getString(R.string.ui_settings);}
    private String rangeLabel(String id){if(UiState.MONTH.equals(id))return getString(R.string.ui_this_month);if(UiState.LAST_30.equals(id))return getString(R.string.ui_last_30_days);return getString(R.string.ui_all);}
    private void today(){
        long now=System.currentTimeMillis();List<Store.Med> active=store.meds(true);List<Store.Log> logs=store.logs();List<Store.Skip> skips=store.skips();TodayPlan raw=TodayPlan.build(active,logs,skips,now,TimeZone.getDefault().getID());TodayFocus focus=new TodayFocus(new TodayFocus.State(){public String get(){return getSharedPreferences("today_focus",0).getString("occurrence_group","");}public void put(String value){getSharedPreferences("today_focus",0).edit().putString("occurrence_group",value).apply();}});TodayPlan plan=focus.apply(raw,active,logs,skips,now,TimeZone.getDefault().getID());nextTickDelay=plan.nextRefreshDelay(now);
        if(!plan.hero.isEmpty()){
            LinearLayout hero=card();hero.setBackground(round(PALE,LINE,16));body.addView(hero,cardParams());
            hero.addView(txt(getString(R.string.ui_currently_due),14,false));
            for(TodayPlan.Row r:plan.hero){TextView name=txt(r.med.name,24,true);name.setPadding(0,dp(8),0,0);hero.addView(name);hero.addView(txt(r.med.dose,18,true));
                hero.addView(txt(scheduleTime(r.plannedAt)+(r.plannedAt<now?getString(R.string.ui_not_recorded_fragment):" · "+relative(r.plannedAt,now)),15,false));
                Button confirm=button(r.plannedAt>now?getString(R.string.ui_record_early):getString(R.string.ui_record_this_dose),true,()->confirm(r.med,r.plannedAt,r.key));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(50));bp.topMargin=dp(8);hero.addView(confirm,bp);
                Button skip=button(getString(R.string.ui_skip_this_dose),false,()->skipOccurrence(r.med,r.plannedAt,r.key));hero.addView(skip,new LinearLayout.LayoutParams(-1,dp(48)));
            }
        }
        msg(String.format(Locale.getDefault(),getString(R.string.ui_today_plan_count),plan.total,plan.completed.size(),plan.skipped.size(),plan.pending()));
        if(!plan.otherDue.isEmpty()){head(getString(R.string.ui_other_due));for(TodayPlan.Row r:plan.otherDue)showOccurrence(r);}
        if(!plan.overdue.isEmpty()){head(String.format(Locale.getDefault(),getString(R.string.ui_previous_pending),plan.overdue.size()));body.addView(txt(getString(R.string.ui_no_dose_not_confirmed),13,false));for(TodayPlan.Row r:plan.overdue)showOccurrence(r);}
        if(!plan.upcoming.isEmpty()){head(getString(R.string.ui_later_today));for(TodayPlan.Row r:plan.upcoming)showOccurrence(r);}
        if(!plan.completed.isEmpty()){act(String.format(Locale.getDefault(),getString(R.string.ui_confirmed_today),plan.completed.size())+(completedExpanded?getString(R.string.ui_collapse):getString(R.string.ui_expand)),()->{completedExpanded=!completedExpanded;render();});if(completedExpanded)for(TodayPlan.Row r:plan.completed)showOccurrence(r);}
        if(!plan.skipped.isEmpty()){act(String.format(Locale.getDefault(),getString(R.string.ui_skipped_today),plan.skipped.size())+(skippedExpanded?getString(R.string.ui_collapse):getString(R.string.ui_expand)),()->{skippedExpanded=!skippedExpanded;render();});if(skippedExpanded)for(TodayPlan.Row r:plan.skipped)showOccurrence(r);}
        if(!plan.later.isEmpty()){act(getString(R.string.ui_future_plan)+(laterExpanded?getString(R.string.ui_collapse):getString(R.string.ui_expand)),()->{laterExpanded=!laterExpanded;render();});if(laterExpanded)for(TodayPlan.Row r:plan.later)showOccurrence(r);}
        if(plan.total==0&&plan.hero.isEmpty())emptyCard(getString(R.string.ui_no_active_plan),getString(R.string.ui_empty_today_help),getString(R.string.ui_add_medication),()->editMed(null));
        if(plan.invalid>0)msg(getString(R.string.ui_invalid_schedule));
        act(getString(R.string.ui_manual_action),this::manual);
    }
    private String relative(long at,long now){long minutes=(long)Math.ceil((at-now)/60000.0);if(minutes<=0)return getString(R.string.ui_scheduled_time_reached);if(minutes<60)return String.format(Locale.getDefault(),getString(R.string.ui_minutes_later),minutes);return String.format(Locale.getDefault(),getString(R.string.ui_hours_minutes_later),minutes/60,minutes%60);}
    private void showOccurrence(TodayPlan.Row row){
        Store.Med m=row.med;long planned=row.plannedAt;Store.Log log=row.log;
        LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(m.name,19,true));c.addView(txt(getString(R.string.ui_planned_dose)+m.dose,15,false));TextView plan=txt(getString(R.string.ui_planned)+scheduleTime(planned),15,true);plan.setPadding(0,dp(8),0,dp(4));c.addView(plan);
        if(log!=null){c.addView(txt(getString(R.string.ui_actual)+actualTime(log.actualAt)+" · "+log.dose,15,false));TextView status=txt(getString(R.string.ui_recorded_status)+displayTiming(log.actualAt,planned),14,true);status.setTextColor(TEAL);c.addView(status);}
        else if(row.skipped){c.addView(txt(getString(R.string.ui_skipped_status),14,true));Button undo=button(getString(R.string.ui_undo_skip),false,()->undoSkip(m,planned,row.key));c.addView(undo,new LinearLayout.LayoutParams(-1,dp(48)));}
        else{c.addView(txt(getString(R.string.ui_not_recorded),14,false));Button b=button(planned>System.currentTimeMillis()?getString(R.string.ui_record_early):getString(R.string.ui_record_this_dose),true,()->confirm(m,planned,row.key));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(50));bp.topMargin=dp(8);c.addView(b,bp);Button skip=button(getString(R.string.ui_skip_this_dose),false,()->skipOccurrence(m,planned,row.key));c.addView(skip,new LinearLayout.LayoutParams(-1,dp(48)));}
    }
    private String timing(long actual,long planned){return actual<planned?getString(R.string.ui_early):actual>planned?getString(R.string.ui_late):getString(R.string.ui_on_schedule);}private String displayTiming(long actual,long planned){return ActualTime.sameDisplayedMinute(actual,planned,ZoneId.systemDefault())?getString(R.string.ui_on_schedule):timing(actual,planned);}

    private void meds(){
        head(getString(R.string.ui_medication_plans));act(getString(R.string.ui_add_med_action),()->editMed(null));
        for(Store.Med m:store.meds(false)){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(m.name+(m.active?"":getString(R.string.ui_paused_suffix)),18,true));c.addView(txt(m.dose,15,false));String schedule=m.scheduleMode.equals(Store.FREQUENCY)?getString(R.string.ui_every)+m.frequencyDays+getString(R.string.ui_days_times)+m.frequencyCount+getString(R.string.ui_times_start)+time(m.anchor):getString(R.string.ui_daily_fixed)+m.times;TextView info=txt(schedule+(blank(m.notes)?"":getString(R.string.ui_notes_prefix)+m.notes),14,false);info.setPadding(0,dp(8),0,dp(10));c.addView(info);LinearLayout row=new LinearLayout(this);c.addView(row);action(row,getString(R.string.ui_edit),()->editMed(m));action(row,m.active?getString(R.string.ui_pause):getString(R.string.ui_resume),()->{store.saveMetadata(m.id,m.name,m.dose,m.notes,!m.active);Alarms.reschedule(this);render();});action(row,getString(R.string.ui_delete),()->new AlertDialog.Builder(this).setMessage(getString(R.string.ui_delete_plan_confirm)).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_delete),(d,w)->{store.deleteMed(m.id);Alarms.reschedule(this);render();}).show());}
    }

    private void statistics(){
        head(getString(R.string.ui_dose_statistics));body.addView(txt(getString(R.string.ui_stats_basis),13,false));
        LinearLayout filters=new LinearLayout(this);filters.setPadding(0,dp(6),0,dp(8));for(String f:new String[]{UiState.ALL,UiState.MONTH,UiState.LAST_30}){Button b=new Button(this);b.setText(rangeLabel(f));b.setAllCaps(false);styleButton(b,f.equals(statsRange));filters.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{statsRange=f;render();});}body.addView(filters);
        long from=0,to=Long.MAX_VALUE;ZoneId zone=ZoneId.systemDefault();LocalDate today=Instant.now().atZone(zone).toLocalDate();
        if(statsRange.equals(UiState.MONTH)){LocalDate start=today.withDayOfMonth(1);from=start.atStartOfDay(zone).toInstant().toEpochMilli();to=start.plusMonths(1).atStartOfDay(zone).toInstant().toEpochMilli();}
        else if(statsRange.equals(UiState.LAST_30)){LocalDate start=today.minusDays(29);from=start.atStartOfDay(zone).toInstant().toEpochMilli();to=today.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli();}
        DoseStats.Summary summary=DoseStats.summarize(store.logs(),from,to);
        if(summary.groups.isEmpty()&&summary.uncounted.isEmpty())emptyCard(getString(R.string.ui_no_stats),getString(R.string.ui_stats_help),null,null);
        for(DoseStats.Group g:summary.groups){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(g.medName,18,true));TextView total=txt(g.totalText()+" "+g.unit,24,true);total.setTextColor(TEAL);total.setPadding(0,dp(8),0,dp(3));c.addView(total);c.addView(txt(g.records+getString(R.string.ui_actual_record_count)+g.unit+getString(R.string.ui_medication_number)+g.medId,13,false));}
        for(DoseStats.Uncounted u:summary.uncounted){LinearLayout c=card();c.setBackground(round(PALE,LINE,14));body.addView(c,cardParams());c.addView(txt(u.medName,17,true));TextView line=txt(getString(R.string.ui_uncounted)+u.records+getString(R.string.ui_text_records),14,false);line.setPadding(0,dp(5),0,0);c.addView(line);}
    }

    private void history(){
        head(getString(R.string.ui_medication_history));act(getString(R.string.ui_manual_action),this::manual);List<Store.Log> logs=store.logs();if(logs.isEmpty())emptyCard(getString(R.string.ui_no_history),getString(R.string.ui_history_help),null,null);
        for(Store.Log l:logs){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(l.medName,18,true));c.addView(txt(l.dose,15,false));String detail=l.manual?getString(R.string.ui_extra_record):getString(R.string.ui_planned)+time(l.plannedAt)+"  ·  "+displayTiming(l.actualAt,l.plannedAt);TextView actual=txt(getString(R.string.ui_actual)+time(l.actualAt)+"\n"+detail+(blank(l.notes)?"":getString(R.string.ui_notes_prefix)+l.notes),14,false);actual.setPadding(0,dp(8),0,dp(8));c.addView(actual);LinearLayout row=new LinearLayout(this);c.addView(row);action(row,getString(R.string.ui_correct),()->editLog(l));action(row,getString(R.string.ui_delete),()->new AlertDialog.Builder(this).setMessage(getString(R.string.ui_delete_record_confirm)).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_delete),(d,w)->{store.deleteLog(l.id);Alarms.reschedule(this);render();}).show());}
    }
    private void settings(){head(getString(R.string.ui_appearance));String mode=getSharedPreferences("appearance",0).getString("mode","system");String[] modes={"system","light","dark"},labels={getString(R.string.ui_follow_system),getString(R.string.ui_light),getString(R.string.ui_dark)};for(int i=0;i<modes.length;i++){final String value=modes[i];Button choice=button(labels[i]+(value.equals(mode)?" ✓":""),value.equals(mode),()->{getSharedPreferences("appearance",0).edit().putString("mode",value).apply();recreate();});body.addView(choice,new LinearLayout.LayoutParams(-1,dp(48)));}head(getString(R.string.ui_reminders_permissions));msg(Alarms.status(this));msg(Alarms.diagnostics(this));act(getString(R.string.ui_enable_notifications),()->Alarms.requestNotifications(this));act(getString(R.string.ui_enable_exact_alarms),()->Alarms.requestExact(this));msg(AlarmSelfTest.status(this));msg(AlarmSelfTest.events(this));act(getString(R.string.ui_start_test),()->{AlarmSelfTest.start(this);toast(getString(R.string.ui_test_scheduled));render();});act(getString(R.string.ui_cancel_test),()->{AlarmSelfTest.cancel(this);render();});msg(getString(R.string.ui_test_explainer));msg(getString(R.string.ui_reminder_safety));}

    private final class CompactDateTime {
        final LinearLayout view=new LinearLayout(MainActivity.this);final Button dateButton=new Button(MainActivity.this),timeButton=new Button(MainActivity.this);final String label;long value;boolean dateChosen,timeChosen;Runnable changed;
        TimeChoices timeChoices;
        CompactDateTime(String label,long initial,boolean chosen){this.label=label;view.setOrientation(0);view.setGravity(Gravity.CENTER_VERTICAL);view.setPadding(0,dp(4),0,dp(4));view.addView(dateButton,new LinearLayout.LayoutParams(0,dp(54),1));view.addView(timeButton,new LinearLayout.LayoutParams(0,dp(54),1));dateButton.setAllCaps(false);timeButton.setAllCaps(false);styleButton(dateButton,false);styleButton(timeButton,false);set(initial,chosen);dateButton.setOnClickListener(v->pickDate());timeButton.setOnClickListener(v->pickTime());}
        void set(long millis,boolean chosen){value=millis;dateChosen=chosen;timeChosen=chosen;update();}
        void onChanged(Runnable r){changed=r;}
        void setTimeChoices(TimeChoices choices){timeChoices=choices;}
        boolean ready(){return dateChosen&&timeChosen;}
        long get(){if(!ready())throw new IllegalArgumentException(getString(R.string.ui_select_date_time));return value;}
        private ZonedDateTime local(){return value>0?Instant.ofEpochMilli(value).atZone(ZoneId.systemDefault()):ZonedDateTime.now();}
        private void update(){ZonedDateTime z=local();dateButton.setText(label+getString(R.string.ui_date)+(dateChosen?z.toLocalDate():getString(R.string.ui_select_date)));timeButton.setText(label+getString(R.string.ui_time)+(timeChosen?(label.equals(getString(R.string.ui_actual_picker))?ActualTime.display(value,ZoneId.systemDefault()).substring(11):clock(z)):getString(R.string.ui_select_time)));}
        private void changed(LocalDate date,LocalTime time){value=ZonedDateTime.of(date,time,ZoneId.systemDefault()).toInstant().toEpochMilli();update();if(changed!=null)changed.run();}
        private void pickDate(){ZonedDateTime z=local();new DatePickerDialog(MainActivity.this,(v,y,m,d)->{LocalDate selected=LocalDate.of(y,m+1,d);boolean newDate=!dateChosen||!selected.equals(z.toLocalDate());if(timeChoices!=null&&newDate)timeChosen=false;LocalTime t=timeChosen?z.toLocalTime():LocalTime.MIDNIGHT;dateChosen=true;changed(selected,t);},z.getYear(),z.getMonthValue()-1,z.getDayOfMonth()).show();}
        private void pickTime(){ZonedDateTime z=local();if(timeChoices!=null){if(!dateChosen){toast(getString(R.string.ui_select_plan_date));return;}List<Long> candidates=timeChoices.forDate(z.toLocalDate());if(candidates.isEmpty()){toast(getString(R.string.ui_no_plan_time));return;}String[] labels=new String[candidates.size()];for(int i=0;i<labels.length;i++)labels[i]=clock(Instant.ofEpochMilli(candidates.get(i)).atZone(ZoneId.systemDefault()));AlertDialog picker=new AlertDialog.Builder(MainActivity.this).setTitle(getString(R.string.ui_select_plan_time)).setItems(labels,(d,which)->{value=candidates.get(which);dateChosen=true;timeChosen=true;update();if(changed!=null)changed.run();}).setNegativeButton(getString(R.string.ui_cancel),null).create();picker.show();styleDialog(picker);return;}new TimePickerDialog(MainActivity.this,(v,h,m)->{timeChosen=true;changed(z.toLocalDate(),LocalTime.of(h,m));},z.getHour(),z.getMinute(),true).show();}
    }

    private void editMed(Store.Med m){
        EditText name=field(getString(R.string.ui_medication_name),m==null?"":m.name),dose=field(getString(R.string.ui_dose_unit),m==null?"":m.dose),times=field(getString(R.string.ui_fixed_times_hint),m==null?"":m.times),days=field(getString(R.string.ui_frequency_days),m==null?"1":String.valueOf(Math.max(1,m.frequencyDays))),count=field(getString(R.string.ui_frequency_count),m==null?"3":String.valueOf(Math.max(1,m.frequencyCount))),notes=field(getString(R.string.ui_notes_optional),m==null?"":m.notes);
        times.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);days.setInputType(InputType.TYPE_CLASS_NUMBER);count.setInputType(InputType.TYPE_CLASS_NUMBER);
        long existingAnchor=m!=null&&Store.FREQUENCY.equals(m.scheduleMode)?m.anchor:0;long initial=Core.initialFrequencyAnchor(System.currentTimeMillis(),TimeZone.getDefault().getID(),existingAnchor);CompactDateTime anchor=new CompactDateTime(getString(R.string.ui_start),initial,true);
        Spinner mode=new Spinner(this);styleSpinner(mode);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{getString(R.string.ui_even_intervals),getString(R.string.ui_fixed_advanced)}));mode.setSelection(m==null||Store.FREQUENCY.equals(m.scheduleMode)?0:1);
        LinearLayout box=box();addField(box,name);addField(box,dose);box.addView(fieldLabel(getString(R.string.ui_reminder_schedule)));box.addView(mode);
        LinearLayout freq=new LinearLayout(this);freq.setOrientation(1);freq.addView(anchor.view);addField(freq,days);addField(freq,count);TextView preview=txt("",14,false);freq.addView(preview);freq.addView(txt(getString(R.string.ui_interval_warning),13,false));
        LinearLayout fixed=new LinearLayout(this);fixed.setOrientation(1);addField(fixed,times);box.addView(freq);box.addView(fixed);addField(box,notes);CheckBox active=new CheckBox(this);active.setText(getString(R.string.ui_reminders_enabled));active.setChecked(m==null||m.active);box.addView(active);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(box);
        Runnable update=()->{boolean f=mode.getSelectedItemPosition()==0;freq.setVisibility(f?View.VISIBLE:View.GONE);fixed.setVisibility(f?View.GONE:View.VISIBLE);if(!f)return;try{List<Long> next=Core.frequencyPreview(anchor.get(),Integer.parseInt(days.getText().toString()),Integer.parseInt(count.getText().toString()),System.currentTimeMillis(),TimeZone.getDefault().getID(),3);StringBuilder b=new StringBuilder(getString(R.string.ui_up_next));for(long at:next)b.append("\n").append(time(at));preview.setText(b.toString());}catch(Exception e){preview.setText(getString(R.string.ui_frequency_help));}};
        mode.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int p,long id){update.run();}public void onNothingSelected(AdapterView<?>a){}});TextWatcher watch=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){update.run();}public void afterTextChanged(Editable e){}};days.addTextChangedListener(watch);count.addTextChangedListener(watch);anchor.onChanged(update);update.run();
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(m==null?getString(R.string.ui_add_medication):getString(R.string.ui_edit_medication)).setView(scroll).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_save),null).create();dialog.setOnShowListener(x->{styleDialog(dialog);dialog.getButton(-1).setOnClickListener(v->{try{int selected=mode.getSelectedItemPosition();if(selected==0){long anchorAt=anchor.get();int d=Integer.parseInt(days.getText().toString()),c=Integer.parseInt(count.getText().toString());boolean same=m!=null&&Store.FREQUENCY.equals(m.scheduleMode)&&anchorAt==m.anchor&&d==m.frequencyDays&&c==m.frequencyCount;if(same)store.saveMetadata(m.id,name.getText().toString(),dose.getText().toString(),notes.getText().toString(),active.isChecked());else store.saveFrequencyMed(m==null?0:m.id,name.getText().toString(),dose.getText().toString(),anchorAt,d,c,notes.getText().toString(),active.isChecked());}else{String fixedTimes=Core.normalizeTimes(times.getText().toString());boolean same=m!=null&&Store.FIXED.equals(m.scheduleMode)&&fixedTimes.equals(m.times);if(same)store.saveMetadata(m.id,name.getText().toString(),dose.getText().toString(),notes.getText().toString(),active.isChecked());else store.saveFixedMed(m==null?0:m.id,name.getText().toString(),dose.getText().toString(),fixedTimes,notes.getText().toString(),active.isChecked());}Alarms.reschedule(this);dialog.dismiss();render();}catch(Exception e){toast(e.getMessage());}});});dialog.show();
    }

    private void confirm(Store.Med med,long planned,String occurrence){
        final TodayActionTarget target=new TodayActionTarget(med,planned,occurrence);
        Core.ConfirmationDefaults defaults=Core.confirmationDefaults(System.currentTimeMillis(),target.plannedDose);long openedAt=defaults.actualAt;String label=openedAt<target.plannedAt?getString(R.string.ui_confirm_early):getString(R.string.ui_confirm_schedule);
        EditText actualDose=field(getString(R.string.ui_actual_dose_unit),defaults.dose);CompactDateTime actual=new CompactDateTime(getString(R.string.ui_actual_picker),defaults.actualAt,true);
        LinearLayout form=box();form.addView(txt(target.medName+getString(R.string.ui_planned_dose_context)+target.plannedDose,16,true));form.addView(txt(getString(R.string.ui_planned_time_unchanged)+scheduleTime(target.plannedAt),14,false));form.addView(txt(getString(R.string.ui_confirm_safety),13,false));addField(form,actualDose);form.addView(actual.view);
        AlertDialog d=new AlertDialog.Builder(this).setTitle(label+getString(R.string.ui_question_mark)).setView(form).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_confirm_and_record),null).create();
        d.setOnShowListener(x->{actionDialogOpen=true;styleDialog(d);d.getButton(-1).setOnClickListener(v->{try{long actualAt=actual.get();validateActual(actualAt);String dose=actualDose.getText().toString();if(!Core.validDose(dose))throw new IllegalArgumentException(getString(R.string.ui_valid_dose));Store.Med current=store.med(target.medId);if(current==null||!current.active||current.revision!=target.revision)throw new IllegalArgumentException(getString(R.string.ui_plan_changed));long result=store.confirm(target.medId,target.revision,target.occurrence,target.plannedAt,actualAt,dose);if(result<0)throw new IllegalArgumentException(getString(R.string.ui_plan_processed));d.dismiss();Alarms.cancelNotice(this,target.occurrence);Alarms.reschedule(this);render();}catch(Exception e){toast(e.getMessage()==null?getString(R.string.ui_check_actual):e.getMessage());}});});d.setOnDismissListener(x->actionDialogOpen=false);d.show();
    }
    private void handle(Intent i){if(i==null||!i.hasExtra("occurrence"))return;String key=i.getStringExtra("occurrence");long id=i.getLongExtra("medId",-1),rev=i.getLongExtra("revision",-1),planned=i.getLongExtra("plannedAt",-1);if(id<=0||rev<=0||planned<=0||key==null||!key.equals(Core.occurrence(id,rev,planned))){i.removeExtra("occurrence");return;}Store.Med m=store.med(id);page=UiState.TODAY;render();if(m!=null&&m.active&&m.revision==rev){if(store.forOccurrence(key)==null&&!store.isSkipped(key))confirm(m,planned,key);}else toast(getString(R.string.ui_reminder_plan_changed));i.removeExtra("occurrence");}

    private void skipOccurrence(Store.Med med,long planned,String key){AlertDialog d=new AlertDialog.Builder(this).setTitle(getString(R.string.ui_skip_confirm)).setMessage(med.name+getString(R.string.ui_planned_time_line)+scheduleTime(planned)+getString(R.string.ui_skip_explainer)).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_skip_this_dose),(x,w)->{long id=store.skipOccurrence(med.id,med.revision,key,planned,TimeZone.getDefault().getID());if(id<0){toast(getString(R.string.ui_skip_failed));return;}Alarms.cancelNotice(this,key);Alarms.reschedule(this);render();}).create();d.setOnShowListener(x->{actionDialogOpen=true;styleDialog(d);});d.setOnDismissListener(x->actionDialogOpen=false);d.show();}
    private void undoSkip(Store.Med med,long planned,String key){if(!store.undoSkip(med.id,med.revision,key,TimeZone.getDefault().getID())){toast(getString(R.string.ui_undo_failed));return;}Alarms.reschedule(this);render();}

    private void manual(){
        List<Store.Med> meds=store.meds(false);if(meds.isEmpty()){toast(getString(R.string.ui_add_first));return;}String[] labels=new String[meds.size()];for(int i=0;i<meds.size();i++)labels[i]=meds.get(i).name+" · "+meds.get(i).dose;
        Spinner medChoice=new Spinner(this);styleSpinner(medChoice);medChoice.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));Spinner kind=new Spinner(this);styleSpinner(kind);kind.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{getString(R.string.ui_extra_record),getString(R.string.ui_link_plan)}));
        EditText dose=field(getString(R.string.ui_actual_dose_unit),meds.get(0).dose),notes=field(getString(R.string.ui_notes_optional),"");CompactDateTime actual=new CompactDateTime(getString(R.string.ui_actual_picker),System.currentTimeMillis(),true),planned=new CompactDateTime(getString(R.string.ui_planned_label),0,false);planned.setTimeChoices(date->{Store.Med selected=meds.get(medChoice.getSelectedItemPosition());String zone=TimeZone.getDefault().getID();return Store.FREQUENCY.equals(selected.scheduleMode)?Core.frequencyOnDate(selected.anchor,selected.frequencyDays,selected.frequencyCount,date,zone):Core.fixedOnDate(selected.times,date,zone);});LinearLayout linked=new LinearLayout(this);linked.setOrientation(1);linked.addView(planned.view);TextView linkedStatus=txt(getString(R.string.ui_choose_plan_date),13,false);linked.addView(linkedStatus);
        LinearLayout form=box();form.addView(kind);form.addView(medChoice);addField(form,dose);form.addView(actual.view);form.addView(linked);addField(form,notes);ScrollView scroll=new ScrollView(this);scroll.addView(form);
        Runnable validateLink=()->{boolean use=kind.getSelectedItemPosition()==1;linked.setVisibility(use?View.VISIBLE:View.GONE);if(!use){linkedStatus.setText(getString(R.string.ui_independent_record));return;}if(!planned.ready()){linkedStatus.setText(getString(R.string.ui_choose_date_time));return;}Store.Med med=meds.get(medChoice.getSelectedItemPosition());long p=planned.get();if(!store.isScheduled(med.id,med.revision,p,TimeZone.getDefault().getID()))linkedStatus.setText(getString(R.string.ui_not_in_schedule));else if(store.isSkipped(med.id,p))linkedStatus.setText(getString(R.string.ui_unskip_before_link));else if(store.forOccurrence(Core.occurrence(med.id,med.revision,p))!=null)linkedStatus.setText(getString(R.string.ui_already_recorded));else linkedStatus.setText(getString(R.string.ui_selected_plan)+scheduleTime(p)+getString(R.string.ui_linked_notice));};
        planned.onChanged(validateLink);kind.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int p,long id){validateLink.run();}public void onNothingSelected(AdapterView<?>a){}});medChoice.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int p,long id){dose.setText(meds.get(p).dose);planned.set(0,false);validateLink.run();}public void onNothingSelected(AdapterView<?>a){}});validateLink.run();
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(getString(R.string.ui_backfill_title)).setView(scroll).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_save_record),null).create();dialog.setOnShowListener(x->{styleDialog(dialog);dialog.getButton(-1).setOnClickListener(v->{try{long actualAt=actual.get();validateActual(actualAt);Store.Med med=meds.get(medChoice.getSelectedItemPosition());long result;if(kind.getSelectedItemPosition()==1){long plannedAt=planned.get();if(!store.isScheduled(med.id,med.revision,plannedAt,TimeZone.getDefault().getID()))throw new IllegalArgumentException(getString(R.string.ui_plan_mismatch));result=store.linkedBackfill(med.id,med.revision,plannedAt,actualAt,dose.getText().toString(),notes.getText().toString(),TimeZone.getDefault().getID());if(result>0)Alarms.reschedule(this);else if(store.isSkipped(med.id,plannedAt))throw new IllegalArgumentException(getString(R.string.ui_unskip_first));}else result=store.manualLog(med.id,dose.getText().toString(),actualAt,notes.getText().toString());if(result<0)throw new IllegalArgumentException(getString(R.string.ui_record_invalid));dialog.dismiss();render();}catch(Exception e){toast(e.getMessage()==null?getString(R.string.ui_check_date_time_dose):e.getMessage());}});});dialog.show();
    }

    private void editLog(Store.Log log){EditText when=field(getString(R.string.ui_actual_time_format),time(log.actualAt)),dose=field(getString(R.string.ui_dose_unit_label),log.dose),notes=field(getString(R.string.ui_notes),log.notes);LinearLayout b=box();addField(b,when);addField(b,dose);addField(b,notes);b.addView(txt(log.plannedAt>0?getString(R.string.ui_linked_plan_unchanged)+time(log.plannedAt):getString(R.string.ui_standalone_no_plan),14,false));AlertDialog d=new AlertDialog.Builder(this).setTitle(getString(R.string.ui_edit_record)).setView(b).setNegativeButton(getString(R.string.ui_cancel),null).setPositiveButton(getString(R.string.ui_save_correction),null).create();d.setOnShowListener(x->{styleDialog(d);d.getButton(-1).setOnClickListener(v->{try{long at=ActualTime.unchangedSaveValue(log.actualAt,when.getText().toString(),ZoneId.systemDefault());if(at<0)at=parse(when.getText().toString());validateActual(at);store.updateLog(log.id,at,dose.getText().toString(),notes.getText().toString());d.dismiss();render();}catch(Exception e){toast(e.getMessage()==null?getString(R.string.ui_check_time_dose):e.getMessage());}});});d.show();}

    private long pickerMillis(DatePicker d,TimePicker t){LocalDate date=LocalDate.of(d.getYear(),d.getMonth()+1,d.getDayOfMonth());LocalTime time=LocalTime.of(t.getHour(),t.getMinute());return ZonedDateTime.of(date,time,ZoneId.systemDefault()).toInstant().toEpochMilli();}
    private void validateActual(long t){if(t<=0)throw new IllegalArgumentException(getString(R.string.ui_actual_positive));if(t>System.currentTimeMillis())throw new IllegalArgumentException(getString(R.string.ui_actual_not_future));}
    private long parse(String s){ParsePosition p=new ParsePosition(0);Date d=fmt.parse(s,p);if(d==null||p.getIndex()!=s.length())throw new IllegalArgumentException(getString(R.string.ui_invalid_time_format));return d.getTime();}
    private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}private String time(long t){return fmt.format(new Date(t));}private String actualTime(long t){return ActualTime.display(t,ZoneId.systemDefault());}
    private String clock(ZonedDateTime z){LocalTime t=z.toLocalTime();if(t.getNano()!=0)return String.format(Locale.ROOT,"%02d:%02d:%02d.%03d",t.getHour(),t.getMinute(),t.getSecond(),t.getNano()/1000000);return t.getSecond()==0?String.format(Locale.ROOT,"%02d:%02d",t.getHour(),t.getMinute()):String.format(Locale.ROOT,"%02d:%02d:%02d",t.getHour(),t.getMinute(),t.getSecond());}
    private String scheduleTime(long millis){ZonedDateTime z=Instant.ofEpochMilli(millis).atZone(ZoneId.systemDefault());return z.toLocalDate()+" "+clock(z);}
    private LinearLayout box(){LinearLayout b=new LinearLayout(this);b.setOrientation(1);b.setPadding(dp(18),dp(8),dp(18),dp(12));b.setBackgroundColor(BG);return b;}
    private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackground(round(SURFACE,LINE,14));return c;}
    private LinearLayout.LayoutParams cardParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);return p;}
    private GradientDrawable round(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private void styleButton(Button b,boolean primary){b.setTextColor(primary?ON_ACCENT:TEAL);b.setTextColor(new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{MUTED,primary?ON_ACCENT:TEAL}));b.setTextSize(14);b.setPadding(dp(12),0,dp(12),0);b.setMinHeight(dp(48));GradientDrawable bg=round(primary?TEAL:PALE,primary?TEAL:LINE,14);android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();states.addState(new int[]{-android.R.attr.state_enabled},round(PALE,LINE,14));states.addState(new int[]{},new android.graphics.drawable.RippleDrawable(ColorStateList.valueOf((TEAL&0x00ffffff)|0x33000000),bg,null));b.setBackground(states);}
    private void styleSpinner(Spinner s){s.setMinimumHeight(dp(48));s.setPadding(dp(10),dp(6),dp(10),dp(6));s.setBackground(round(SURFACE,LINE,10));}
    private Button button(String label,boolean primary,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);styleButton(b,primary);b.setOnClickListener(v->run.run());return b;}
    private void styleDialog(AlertDialog d){Button pos=d.getButton(-1),neg=d.getButton(-2);if(pos!=null)styleButton(pos,true);if(neg!=null)styleButton(neg,false);}
    private void emptyCard(String title,String detail,String action,Runnable run){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(title,18,true));TextView d=txt(detail,14,false);d.setPadding(0,dp(5),0,dp(8));c.addView(d);if(action!=null)c.addView(button(action,true,run));}
    private EditText field(String hint,String value){EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setHint(hint);e.setTag(hint);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(round(SURFACE,LINE,10));e.setMinHeight(dp(48));return e;}
    private void addField(LinearLayout b,EditText e){b.addView(fieldLabel((String)e.getTag()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);b.addView(e,p);}
    private TextView fieldLabel(String s){TextView v=txt(s,13,false);v.setPadding(0,dp(6),0,dp(4));return v;}
    private TextView txt(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(bold?INK:MUTED);if(bold)t.setTypeface(null,1);return t;}
    private void head(String s){TextView t=txt(s,21,true);t.setPadding(0,dp(8),0,dp(8));body.addView(t);}private void title(String s){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(s,18,true));}private void msg(String s){LinearLayout c=card();body.addView(c,cardParams());c.addView(txt(s,14,false));}
    private void act(String s,Runnable r){Button b=button(s,true,r);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.bottomMargin=dp(10);body.addView(b,p);}private void action(LinearLayout row,String s,Runnable r){Button b=button(s,false,r);if(s.equals(getString(R.string.ui_delete)))b.setTextColor(RED);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(b,p);}
    private boolean blank(String s){return s==null||s.trim().isEmpty();}private void toast(String s){Toast.makeText(this,s==null?getString(R.string.ui_operation_failed):s,Toast.LENGTH_LONG).show();}
}
